-- ============================================================================
-- BossTips Raid Guide Data —— 版本 12.1 团本攻略
-- 实例 key 为国服名；首领 key 为国服名；encounterId 取自 BigWigs/DBM（原样保留）。
-- 攻略格式：{rt8}名字{rt8}||[机制]描述||{rt1}必断/速杀：…{rt1}||坦：…治疗：…输出：…
-- 分难度：tipsByDifficulty 支持 lfr/normal/heroic/mythic/mythicplus（缺档位进游戏时回退通用 tips）。
-- ============================================================================
local _, addon = ...
addon.GuideData = addon.GuideData or { versions = {}, mplus = {}, raids = {} }
addon.GuideData.raids = addon.GuideData.raids or {}
addon.GuideData.raids["12.1"] = addon.GuideData.raids["12.1"] or {}
addon.GuideData.meta = addon.GuideData.meta or {}

-- ===================== 烈毒之渊 (instanceId 3004) =====================
addon.GuideData.raids["12.1"]["烈毒之渊"] = {
    ["盘魂者内克扎莉"] = { order = 1, type = "BOSS", tips = [=[{rt8}盘魂者内克扎莉{rt8}||[机制摘要]场地正中是[盘魂之井]：[无眠的阿曼尼]走进井里、或玩家死在井里都会触发[盘魂仪式]，给BOSS+5能量并让全团叠一层44秒DOT与易伤，能量攒满释放[溃散之怒]直接灭团。[盘魂]会夺魂拉人走向井口，触水即被献祭。血量50%进入[觉醒仪式]，击杀[贾瓦埃的回响]解除[觉醒之缚]把她拉回战场；满能量后进入[解除盘卷]软狂暴阶段。||{rt1}必断/速杀：全程控停[无眠的阿曼尼]绝不让它们进井；[盘魂点燃]4秒引导期间躲开[苦痛回响]击退圈；史诗打断[盘魂者诅咒]与[祈求]{rt1}||坦：把BOSS拉离井口，[精华撕裂]结束后立刻清掉留下的[潜藏的教徒]。 治疗：[盘魂点燃]是全团高伤窗口，一轮触发5次[盘魂仪式]，提前铺盾并配团减。 输出：优先级为控怪拦截 > 转火[贾瓦埃的回响] > [解除盘卷]阶段全爆发。]=], tipsByDifficulty = {lfr = [=[只需记住三件事：中间那口井里的黑水不要站，小怪不要放进井里，被[盘魂]拉着走时原地等打断或驱散。BOSS掉到一半会撤退，这时集火场上的[贾瓦埃的回响]把她拉回来。最后阶段全团掉血变快，交个人减伤跟紧治疗。]=], normal = [=[安排两组人轮流用减速与控制拦停[无眠的阿曼尼]，一只都不要放进[盘魂之井]。[盘魂点燃]的4秒引导前铺好盾，引导中同时躲[苦痛回响]的击退小圈；[精华撕裂]结束后顺手清掉[潜藏的教徒]。50%集火[贾瓦埃的回响]，[解除盘卷]是软狂暴，嗜血留到这个阶段一次打完。]=], heroic = [=[英雄额外附加[仪式灼烧]，每层让[盘魂仪式]伤害再提高15%且持续1分钟，所以一次漏怪就会让后面雪崩，控怪链必须零失误。[盘魂点燃]要固定用团减加额外治疗CD顶过去，DOT与易伤层数高时不要硬吃。尽量在易伤层数堆起来之前推进阶段，避免带着满层进[解除盘卷]。]=], mythic = [=[阶段转换新增[紧攫深渊]：[溺亡的回响]周期性把全团往井口拉并持续掉血，必须尽快击杀；进井输出的人离开时会带[灵魂疲惫]（受井与[不朽缠绕]伤害+300%），要排轮换名单进出。[祈求]阶段必须断满所有[潜藏的教徒]的施法，被打断的施法者会让打断人沉默3秒，因此踢断表要按人排死。整场几乎零容错，一次进井或漏断基本等于重开。]=]} },
    ["陵寝哨兵"] = { order = 2, type = "BOSS", tips = [=[{rt8}陵寝哨兵{rt8}||[机制摘要][乌拉特克之息]（活化毒液）与[乌拉特克之血]（感染玩家）必须始终拉开40码以上，一旦靠近就获得[乌拉特克之统御]99%减伤，直接打不动。两只血量要平推：满能量时它们会聚拢释放[强酸静滞]，把血量较低的哨兵治疗到与另一只齐平，同时给全团挂[螺旋毒素]——必须与同样中毒的玩家互撞、精确叠到4层才会完全中和。||{rt1}必断/速杀：[毒液凝块]大软要集火（存活期间持续[污染]全团AOE）；[剧毒水滴]必须在16秒内全部踩掉，漏掉就会[剧毒冲击]灭团{rt1}||坦：分左右各拉一只，[强化猛击]与[鲜血毒液注射]连续命中同一目标会越打越痛，按层数换坦。 治疗：[凋零之血]要及时驱散，否则引发[鲜血毒液]；[污染]是全团巨额伤害。 输出：两只血量差控制在3%以内，绝不单推一只。]=], tipsByDifficulty = {lfr = [=[核心只有一条：两只哨兵永远分开站，别把它们拉到一起，否则它们会有99%减伤。绿色那只喷出的[剧毒水滴]要主动跑上去踩掉，全部踩完才不会爆炸。身上挂[螺旋毒素]后去找一个同样中毒的人撞一下，叠到4层就会自动消失。]=], normal = [=[两坦分左右各带一只，中间空出至少40码；DPS分成两队各打一只，血量同步压，别让[强酸静滞]白奶回来。全员分工踩[剧毒水滴]并集火[毒液凝块]，治疗盯死[凋零之血]的驱散。[螺旋毒素]事先编好两人一组的碰撞对，撞到4层即可。]=], heroic = [=[英雄的[活体毒液]在喷出4秒后会飞回源头，要提前让开回程路线不要站在连线上。[螺旋毒素]必须精确4层，多撞或少撞都会留下持续伤害，配对表要固定到人。坦克按[强化猛击]层数固定轮换，交换场地时不能脱手让两只贴到一起。]=], mythic = [=[分离容差进一步收紧，两只冲到一起放大招时大团要分成两队并定期交换场地，交换过程中顺手完成换坦。血量必须严格同步，否则[强酸静滞]奶回来的血量会直接吃掉一整轮爆发。任何一次[螺旋毒素]错撞都会带着DOT进入下一轮，节奏一旦乱掉很难补回来。]=]} },
    ["迷失的探险者"] = { order = 3, type = "BOSS", tips = [=[{rt8}迷失的探险者{rt8}||[机制摘要]三只始祖龟（[大副纳玛]/[商人盖博]/[书卷贤者伊库]）必须彼此拉开，只要两只靠在一起就由纳玛提供[团结光环]99%减伤。血量要平均压，[书卷贤者伊库]留到最后杀——任何一只先死都会让其余获得[无情加剧]（每秒+100%伤害）与[粉碎铁锹]。场外的[莫尔扎希]用[黑暗低语]附身控制它们，拿[恶心的鱼]砸醒被附身的目标，否则他会用[束缚苦痛]重夺控制并解锁新技能。||{rt1}必断/速杀：打断[书卷贤者伊库]的[寒冰烈焰]；[恶心的鱼]优先砸还没被鱼砸过的目标{rt1}||坦：躲开纳玛正面的[旋壳]（4秒昏迷），按[稳固打击]层数换坦。 治疗：[恶毒威仪]每2秒全团掉血，近战堆预铺HoT。 输出：[巨力重击]标记3人要分三组去各自落点分摊，空放会全团重伤；[霜火弹幕]分散站，绝不让两颗球合并成[元素爆炸]。]=], tipsByDifficulty = {lfr = [=[三只龟龟站得越散越好，挤在一起它们就有99%减伤根本打不动。地上会掉箱子、弹跳蘑菇和震荡炸弹，看到就走开，被炸飞后注意落点。捡到[恶心的鱼]就往被控制的龟身上砸，能把它救回来。]=], normal = [=[提前分三组分别去接[巨力重击]的三个落点做分摊，没人接会全团重伤。打断[书卷贤者伊库]的[寒冰烈焰]，[霜火弹幕]分散站防止两球合并。三只血量同步压，最后留[书卷贤者伊库]，不要提前打死任何一只。]=], heroic = [=[[真菌爆炸]与[冲击波]一碰就是百万级伤害，[爆炸惊喜]击飞后要控制好落点不要落进蘑菇里。[莫尔扎希]满能量会狂暴，[恶心的鱼]要卡在[黑暗低语]刚上手时就砸掉，并优先砸没被砸过的目标。击杀顺序失误触发[无情加剧]基本等于灭团，斩杀阶段要统一指挥。]=], mythic = [=[小怪血量与计时全面收紧，分摊、打断、砸鱼三条链必须同时不掉线。三只血量差要压到极小，做到近乎同时进入斩杀，不留任何[无情加剧]窗口。近战堆要同时兼顾[粉碎铁锹]的击退与[邪眼]2码扫射，站位需随雕像轮换实时调整。]=]} },
    ["万毒邪祟者瓦什尼克"] = { order = 4, type = "BOSS", tips = [=[{rt8}万毒邪祟者瓦什尼克{rt8}||[机制摘要]BOSS缓慢攒满能量后对最近的两座喷泉施放[痛饮]，坦克带位就决定了这一轮出哪两种大软。三种大软（鲜血[结块毒液]、暗影[凝聚的毒液]、烈焰[燃烧剧毒]）爬进[万毒之穴]就触发[恶性爆发]灭团，必须在半路拦停清掉。[适应性感染]会随被痛饮的喷泉切换成虹吸/爆炸/冥河三种版本，[灌注]层数还会让软怪血量与喷射伤害持续放大。||{rt1}必断/速杀：所有大软必须在抵达[万毒之穴]前处理掉；[结块毒液]带[猩红坚韧]免疫控制只能硬集火，死后还会[分裂结块]{rt1}||坦：吃[滴毒之牙]（+100%物理易伤32秒）按层换坦，并在[痛饮]的施放间隙把BOSS带到想要的喷泉组合。 治疗：[虹吸感染]带866k治疗吸收还会[鲜血虹吸]抽队友，[冥河感染]带577k吸收，都要预先点刷吸收盾。 输出：被[瘟疫泡沫]点名要把[瘟疫浪潮]的喷发方向朝外；[燃烧剧毒]别和其他大软同时死，避免[腐蚀涌动]伤害重叠。]=], tipsByDifficulty = {lfr = [=[看到从喷泉爬出来的大软就集火，绝对不要让它爬到房间中间的坑里。身上出现[瘟疫泡沫]时跑到人堆外面，等毒液喷完再回来。被[爆炸感染]点名就跑远，另外两种感染留在原地让治疗奶就行。]=], normal = [=[坦克通过带位固定[痛饮]的喷泉组合，尽量避开难处理的搭配。分好近战与远程各拦一条软怪路线，控制技能对暗影和烈焰软有效，鲜血软免控只能硬打。[燃烧剧毒]与其他大软错开时间击杀，避免[腐蚀涌动]和[幽影喷射]叠在一起。]=], heroic = [=[英雄增加[恶行催化剂]：万毒之穴上方凝出毒液宝珠，全团先吃一次高额毒素伤害，随后飞散的[催化胆汁]必须有人接住，空放会改为全团掉血。喷泉排空更快，[灌注]层数叠上来后软怪血量与喷射伤害翻倍，清怪节奏必须提速。[滴毒之牙]的物理易伤期间治疗要盯死坦克并配合外部减伤。]=], mythic = [=[史诗额外加入原型毒液的配对与站位层，容错接近于零，任何一只软进坑就是重开。三种[适应性感染]会重叠出现，需要预排驱散、吸收盾与外场爆炸位的轮换表。全程按[痛饮]节拍走，爆发窗口卡在[毒性蒸汽]层数还低的前几轮。]=]} },
    ["斯索拉克"] = { order = 5, type = "BOSS", tips = [=[{rt8}斯索拉克{rt8}||[机制摘要][顶级掠食者]是一套固定连招：正面锥形[劫掠]只能坦克单吃（造成+300%劫掠易伤且可叠加）、[毁伤]同样是正面锥形但需要人分摊、随后[风暴]毒漩涡向外飞射要躲。全场被[狂怒侧风]反复吹动，结束时挂[湍流阵风]需要与另一名受影响玩家接触才能解除；战斗后期汇聚成[呼啸旋涡]把所有人吹飞。[毒液涌动]点名后爆炸并留下[粘稠囊肿]，碰到就把全团击退。||{rt1}必断/速杀：[掘地固守]期间BOSS免疫强制位移但受到伤害提高30%，持续25秒，嗜血与全部爆发都交在这个窗口{rt1}||坦：正面[劫掠]严禁扫到团队，按[劫掠]与[侵蚀毒液]层数换坦。 治疗：[乌拉特克之仪]每2秒全团掉血，[顶级掠食者]连招期间坦克压力极大。 输出：被[毒液涌动]点名跑外场分散爆炸，把[粘稠囊肿]放在不挡路的位置；囊肿毒素能让人更稳地贴地，可用来对抗吹风。]=], tipsByDifficulty = {lfr = [=[站在BOSS侧后方，不要吃正面的锥形攻击。被绿色毒液点名就跑到人少的地方，爆炸后留下的毒球不要去碰。刮大风把你吹起来时，去撞一个同样被吹起的队友就能落地。]=], normal = [=[[毁伤]要安排足够人数一起分摊，人太少会直接把接的人打死。[狂怒侧风]结束会把你吹飞并挂[湍流阵风]，提前找好互撞的搭档解除。[掘地固守]的25秒是唯一的+30%易伤窗口，把嗜血和爆发全压在这里。]=], heroic = [=[[粘稠囊肿]会在场上越铺越多，放置位置要提前规划出通行路线，[呼啸旋涡]期间没有落脚点就等于送人头。坦克[劫掠]叠层后承伤成倍上涨，需要外部减伤配合固定的换坦点。[侵蚀毒液]与[风暴]的中毒减速叠在一起时移动会很吃力，留好位移技能。]=], mythic = [=[史诗加入[毒蛇之怒]：被标记玩家8码内必须凑够14人才会触发[大开杀戒]，人数不够BOSS就会攒满怒气进[怒不可遏]直接灭团。[大开杀戒]留下的[剧毒]在被移除时会爆炸并留下[腐蚀残渣]（站内+30%承伤），驱散时机与站位必须统一指挥。全程在“凑人分摊”与“分散躲风”之间来回切换，节奏错一次就补不回来。]=]} },
    ["双子毒牙"] = { order = 6, type = "BOSS", tips = [=[{rt8}双子毒牙{rt8}||[机制摘要]核心是[永恒毒液]：几乎所有技能都会给层数，每层每秒持续掉血，叠到10层直接暴毙。唯一消层手段是伊斯拉兹的[贪婪盛宴]——由14码内玩家分摊三次连续吞噬，每次命中消耗被击中玩家1层；英雄以上被吞下的毒液会化成[血团凝块]，必须转火否则[鲜血喷涌]每4秒给它叠15%增伤。两条蛇要一起死，先死一只会让存活者获得[怒涌]每4秒+25%伤害。||{rt1}必断/速杀：[维克苏尔之嗣]与[血团凝块]最优先转火；[碎石击]必须有人在3码内接住，空放全团吃无视护甲的高额击退伤害{rt1}||坦：维克苏尔的[浓缩唾液]与伊斯拉兹的[凝血箭]要求坦克贴在近战范围内不能脱手，按[碎裂]层数换坦。 治疗：[剧毒烟气]每2秒全团掉血，[贪婪盛宴]分摊瞬间要交团减。 输出：[腐蚀洪流]喷出的液滴安排单人去接（个人+1层）而不是不接让全团+1层；[盘绕毒素]贴边分散放圈，结束后离开[毒性黏液]。]=], tipsByDifficulty = {lfr = [=[身上的[永恒毒液]层数是命门，快到上限时一定要站进伊斯拉兹的[贪婪盛宴]分摊范围里消层。地上的绿色黏液和飘着的毒球不要踩、不要碰。看到小蛇[维克苏尔之嗣]刷出来立刻转火打掉，它每发唾液都会给你加层数。]=], normal = [=[两坦分别贴住两条蛇，[碎石击]一定要有人在3码内接住。安排固定的人去接[腐蚀洪流]喷出的液滴，避免让全团一起吃层数。双头血量同步压，最后同时击杀，不要留出[怒涌]窗口。]=], heroic = [=[英雄的[贪婪盛宴]会把吞下的毒液变成[血团凝块]，[起泡混合物]让它随层数变大变厚，必须立刻集火，否则[鲜血喷涌]会持续叠加全团增伤。满能量时维克苏尔的[涌动]与伊斯拉兹的[洪流]同时到来，需要提前留好团减和治疗大技能。[凝固血肉]的血池会压缩场地，站位要预留撤退空间。]=], mythic = [=[层数管理精确到人：接液滴、进[贪婪盛宴]、吃[搅动深渊]都要按表轮换，任何一次多吃都可能顶到10层暴毙。[血团凝块]要按正确顺序喂给伊斯拉兹，处理不干净就会带着叠满的[鲜血喷涌]进下一轮。收尾必须让两条蛇同时倒下，误差控制在几秒之内。]=]} },
    ["盘卷祭坛"] = { order = 7, type = "BOSS", tips = [=[{rt8}盘卷祭坛{rt8}||[机制摘要]前半段打祖尔加：[断头台]必须有人进圈分摊，同时躲开飞出的战斧与地面上的[凝聚毒液]，身上的[毒牙]debuff要驱散。血量过半后[妖术领主玛拉卡斯]直接附身，战斗转入[恐惧行军]与[灵魂割裂]阶段，[幽暗炸弹]会挂上[墓缚]，需要去捡[灵魂碎片]解除。最终阶段两人分离同场作战且血量互相关联，必须一起收掉。||{rt1}必断/速杀：打断[恶毒盘魂者]的[恐惧尖啸]并立刻杀掉；被[恐惧化身]锁定时要拉着风筝跑，不能站着硬吃{rt1}||坦：飞斧路径与[断头台]落点要提前站好，附身阶段技能组整体更换，减伤按新节奏重排。 治疗：[墓缚]期间目标承伤显著上升，捡到碎片前要顶住。 输出：分摊[断头台]后注意脚下的[凝聚毒液]再归位；最终阶段要同时兼顾战士的物理压制与妖术领主的法系爆发。]=], tipsByDifficulty = {lfr = [=[前半段跟着人堆走：[断头台]要站进去一起分摊，地上的毒液和飞出来的斧子躲开。玛拉卡斯出现后会有小怪盯着你追，边跑边打不要站着挨。身上出现[墓缚]时去捡地上的[灵魂碎片]就能解掉。]=], normal = [=[分好[断头台]的分摊组，人数不足会把接的人直接打死。打断[恶毒盘魂者]的[恐惧尖啸]，[恐惧化身]锁定谁就由谁负责风筝，其他人不要挡路。最终阶段两个目标血量联动，提前算好爆发把它们同时打死。]=], heroic = [=[[凝聚毒液]会在场上不断累积，分摊与风筝的路线必须同时避开毒液，位移技能要留着用。附身阶段的[恐惧行军]与[灵魂割裂]会和小怪波重叠，打断表和转火表要拆成两组人分别负责。最终阶段双目标同时输出压力很大，团减与治疗CD留到这里再交。]=], mythic = [=[容错极低：斧线、[断头台]落点、[凝聚毒液]与[恐惧化身]的移动路线都要预先规划成固定跑法。[幽暗炸弹]与[墓缚]需要按人轮换去捡碎片，漏掉一个人就会在下一波直接倒。最终阶段必须做到两个目标几乎同时死亡，否则存活方的增伤会瞬间打穿治疗。]=]} },
    ["乌拉特克"] = { order = 8, type = "BOSS", tips = [=[{rt8}乌拉特克{rt8}||[机制摘要]三阶段尾王，可站区域会逐步塌陷。P1[腐蚀之翼]把毒液波推过全场，路线经过蛇卵就会孵出[吞噬者之嗣]，重点是控制波的走向而不是无脑清卵；[腐臭薄膜]会把人隔离必须速破，坦克保持近战距离避免[失控之怒]。P2[受缚者之怒]暴露[剧毒之心]，是全场唯一的大爆发窗口，同时要躲[坠落碎石]。P3[幽灵盘绕]与[拆毁]不断拆掉场地，[狂怒解放]是硬狂暴。||{rt1}必断/速杀：[吞噬者之嗣]与[腐臭薄膜]优先处理；P2[剧毒之心]窗口交嗜血与全部爆发{rt1}||坦：全程保持在近战范围内，P3提前占好不会被[拆毁]吃掉的位置。 治疗：P2的[坠落碎石]与环境伤害持续叠加，双治疗CD要分开安排在两个放大窗口。 输出：P3提前往安全地面转移，不要把位移浪费在无效走位上；[狂怒解放]之前必须打完，属于纯竞速。]=], tipsByDifficulty = {lfr = [=[跟紧人堆，看到地上蔓延的毒液波就绕开，别去踩蛇卵孵出来的小怪堆。有人被薄膜包住时优先打开救人。BOSS露出心脏的阶段是集中输出的时候，把大招都交出来。]=], normal = [=[毒液波的走向由团队控制，指挥安排推向哪一侧以减少孵化出的[吞噬者之嗣]。[受缚者之怒]暴露[剧毒之心]时嗜血爆发一次打满。最后阶段场地会被拆掉，提前往安全地面集中，不要留在边缘等着掉下去。]=], heroic = [=[阶段转换之间几乎没有喘息，[坠落碎石]与环境伤害持续叠加，治疗CD要精确卡在两个放大窗口上。孵化控制要求更严，一次错误的波路线会同时刷出多只[吞噬者之嗣]导致人手不够。P3[幽灵盘绕]必须全团按时堆到冲击区，散开就是灭团。]=], mythic = [=[史诗新增机制并把软狂暴变成硬性检查，[狂怒解放]之前必须结束战斗。毒液波路线、蛇卵孵化顺序与塌陷区域要写成完整跑法逐轮执行。近战与远程分区轮换，保证[剧毒之心]窗口内不掉输出，任何一次站位失误都会连锁影响到下一阶段。]=]} },
}
