-- ===================== 潮缚石窟 (instanceId 2987) =====================
addon.GuideData.raids["12.1"]["潮缚石窟"] = {
    ["尼姆瑞莎·唤波者"] = { order = 1, type = "BOSS", tips = [=[{rt8}尼姆瑞莎·唤波者{rt8}||[机制摘要]单首领巢穴战，四个技能按约20秒一轮的节拍循环：坦克指向的直线[水流疾风]（史诗替换为更凶的[水流喷射]）要让开射线；[魅惑气泡]从场地边缘召出鱼人小怪，必须在它们抵达中央前清掉；[冰寒之霜]点名后按提示远离或跑向寒冰球；[深渊之雨]是全团AOE治疗检查。[无尽潮汐]为10分钟硬狂暴。||{rt1}必断/速杀：[魅惑气泡]召出的鱼人优先集火，减速与控制全丢在它们身上；[破潮者冲锋]要注意脚下提前让出路径{rt1}||坦：把直线技能的射线拉向空场，别让它扫过治疗与远程的站位。 治疗：[深渊之雨]提前铺盾与团减，并和[冰寒之霜]的移动窗口错开。 输出：清怪与转火BOSS的节奏按气泡计数走，不要为了输出漏怪。]=], tipsByDifficulty = {lfr = [=[世界难度容错很高：跟着大部队打，边缘刷出来的鱼人小怪看到就顺手清掉。坦克面前的直线水流不要站在射线上。全团掉血的[深渊之雨]期间站好别乱跑，让治疗把血线奶满。]=], normal = [=[分配远程与带减速的职业专门拦[魅惑气泡]刷出的鱼人，不让它们走进中间。[冰寒之霜]点名后按提示移动，不要把寒冰球带进人堆。[深渊之雨]前提前铺盾，坦克始终把直线技能引向空地。]=], heroic = [=[各技能约20秒一轮且会互相重叠，[魅惑气泡]的小怪波与[深渊之雨]同时到来时要先保住团队血线再清怪。[破潮者冲锋]的路径要提前空出来，被撞到还会连带吃后续伤害。全程盯[无尽潮汐]计时，清怪拖太久会被狂暴追上。]=], mythic = [=[神话把[水流疾风]换成更凶的[水流喷射]，坦克必须精准控制射线方向并按提示轮换承受。鱼人小怪的数量与刷新更密，需要固定两组人负责左右两侧且不占用BOSS的输出窗口。[冰寒之霜]与[深渊之雨]重叠的窗口要预排团减，狂暴前的DPS余量很小。]=]} },
}
addon.GuideData.meta["潮缚石窟"] = { isRaid = true, instanceId = 2987, encounterIds = {
    ["尼姆瑞莎·唤波者"] = 3379,
} }

